SELECT query_id,hostname,type,query_start_time_microseconds AS started_at_utc,event_time_microseconds AS finished_at_utc,
query_duration_ms,read_rows,read_bytes,result_rows,result_bytes,memory_usage AS peak_memory_bytes,peak_threads_usage,
normalized_query_hash,query_cache_usage,exception_code,
ProfileEvents['UserTimeMicroseconds'] AS user_cpu_us,ProfileEvents['SystemTimeMicroseconds'] AS system_cpu_us,
ProfileEvents['OSCPUWaitMicroseconds'] AS cpu_wait_us,ProfileEvents['OSIOWaitMicroseconds'] AS io_wait_us,
toJSONString(ProfileEvents) AS profile_events_json,toJSONString(Settings) AS settings_json
FROM clusterAllReplicas(default,merge('system','^query_log'))
WHERE event_date='2026-10-11' AND event_time>=toDateTime('2026-10-11 09:30:00','UTC')
AND query_id IN ('reader-scaling-20261011T093715Z-pilot-1-D1-t2','reader-scaling-20261011T093715Z-pilot-2-D1-t4','reader-scaling-20261011T093715Z-pilot-3-D1-t1','reader-scaling-20261011T093715Z-pilot-4-D1-t16','reader-scaling-20261011T093715Z-pilot-5-D1-t8','reader-scaling-20261011T093715Z-pilot-6-D2-t16','reader-scaling-20261011T093715Z-pilot-7-D2-t1','reader-scaling-20261011T093715Z-pilot-8-D2-t2','reader-scaling-20261011T093715Z-pilot-9-D2-t4','reader-scaling-20261011T093715Z-pilot-10-D2-t8','reader-scaling-20261011T093715Z-pilot-11-A1-t4','reader-scaling-20261011T093715Z-pilot-12-A1-t16','reader-scaling-20261011T093715Z-pilot-13-A1-t8','reader-scaling-20261011T093715Z-pilot-14-A1-t1','reader-scaling-20261011T093715Z-pilot-15-A1-t2','reader-scaling-20261011T093715Z-pilot-16-A2-t16','reader-scaling-20261011T093715Z-pilot-17-A2-t1','reader-scaling-20261011T093715Z-pilot-18-A2-t2','reader-scaling-20261011T093715Z-pilot-19-A2-t4','reader-scaling-20261011T093715Z-pilot-20-A2-t8','reader-scaling-20261011T093715Z-pilot-21-A3-t1','reader-scaling-20261011T093715Z-pilot-22-A3-t8','reader-scaling-20261011T093715Z-pilot-23-A3-t4','reader-scaling-20261011T093715Z-pilot-24-A3-t2','reader-scaling-20261011T093715Z-pilot-25-A3-t16','reader-scaling-20261011T093715Z-pilot-26-A4-t1','reader-scaling-20261011T093715Z-pilot-27-A4-t16','reader-scaling-20261011T093715Z-pilot-28-A4-t8','reader-scaling-20261011T093715Z-pilot-29-A4-t4','reader-scaling-20261011T093715Z-pilot-30-A4-t2') AND is_initial_query=1 AND type IN ('QueryFinish','ExceptionWhileProcessing','ExceptionBeforeStart')
ORDER BY query_start_time_microseconds LIMIT 2000 SETTINGS max_threads=2,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=1000000000,max_bytes_to_read=100000000000,skip_unavailable_shards=0 FORMAT CSVWithNames